def nums(o, key):
    out=[]
    if isinstance(o,dict):
        for k,v in o.items():
            if k==key and isinstance(v,(int,float)): out.append(v)
            out += nums(v,key)
    elif isinstance(o,list):
        for v in o: out += nums(v,key)
    return out
for f in sorted(glob.glob(os.path.join(D,'phase[12]-task-*.jsonl'))):
    first=last=None; out=inp=0; idle=0; errors=0; assistant=0
